// Validate YAML text with eemeli/yaml (YAML 1.2). Usage:
//   node validate_yaml.js file.yaml            -> whole stream
//   node validate_yaml.js --stdin label        -> read YAML from stdin
const YAML = require('/usr/share/nodejs/tap-yaml/node_modules/yaml');
const fs = require('fs');

function check(src, label) {
  const docs = YAML.parseAllDocuments(src, { version: '1.2', merge: true, prettyErrors: true });
  let bad = 0;
  docs.forEach((d, i) => {
    for (const e of d.errors) {
      bad++;
      console.log(`${label}: doc ${i}: ERROR ${e.name}: ${e.message}`);
    }
    for (const w of d.warnings) {
      console.log(`${label}: doc ${i}: warning ${w.name}: ${w.message}`);
    }
  });
  if (!bad) {
    console.log(`${label}: OK (${docs.length} document(s))`);
  }
  return bad;
}

const args = process.argv.slice(2);
let bad = 0;
if (args[0] === '--stdin') {
  bad += check(fs.readFileSync(0, 'utf8'), args[1] || 'stdin');
} else if (args[0] === '--json') {
  // print parsed JSON of the stream for eyeballing semantics
  const docs = YAML.parseAllDocuments(fs.readFileSync(args[1], 'utf8'), { version: '1.2', merge: true });
  for (const d of docs) console.log(JSON.stringify(d.toJSON(), null, 1));
} else {
  for (const f of args) bad += check(fs.readFileSync(f, 'utf8'), f);
}
process.exit(bad ? 1 : 0);

